insert into public.admission_offerings (
  offering_id, year, province_slug, major_slug, school_slug, program_names, exam_scheme_id,
  training_site, eligible_major_categories, public_subjects, professional_subjects, plan_count,
  charter_url, syllabus_url, source_status, verified_at, active, status, sort_order
)
select source.id, 2026, 'anhui', 'all-programs', source.school, array[source.program], source.scheme,
  source.site, source.eligible,
  array(select jsonb_array_elements_text(source.public)),
  array(select jsonb_array_elements_text(source.professional)),
  source.plan, source_urls.charter_url, source_urls.syllabus_url,
  '2026招生章程与专业课考试大纲已核验', date '2026-10-19', true, 'published', source.sort
from source join source_urls using (school);

do $$
declare
  target record;
  actual_rows integer;
  actual_programs integer;
  actual_plans integer;
begin
  for target in
    select * from (values
    ('hfnu',28,26,2000),
    ('hnnu',18,18,1500),
    ('slu',16,16,2000),
    ('ahstu',6,4,300),
    ('tlu',6,5,200),
    ('fyut',6,5,400),
    ('auta',5,5,500),
    ('ahut',15,11,740)
    ) as expected(school_slug, offering_rows, program_count, plan_total)
  loop
    select count(*), count(distinct program_name), sum(plan_count)
      into actual_rows, actual_programs, actual_plans
    from (
      select o.plan_count, unnest(o.program_names) as program_name
      from public.admission_offerings o
      where o.year = 2026 and o.status = 'published' and o.active = true and o.school_slug = target.school_slug
    ) expanded;
    if actual_rows <> target.offering_rows or actual_programs <> target.program_count or actual_plans <> target.plan_total then
      raise exception 'Batch fourteen stopped: % totals are %, %, %, expected %, %, %', target.school_slug,
        actual_rows, actual_programs, actual_plans, target.offering_rows, target.program_count, target.plan_total;
    end if;
  end loop;

  if exists (
    (select row_data from batch_fourteen_protected_offering_drafts except select to_jsonb(o) from public.admission_offerings o where o.status <> 'published' or o.active = false)
    union all
    (select to_jsonb(o) from public.admission_offerings o where o.status <> 'published' or o.active = false except select row_data from batch_fourteen_protected_offering_drafts)
  ) then raise exception 'Batch fourteen stopped: protected draft/inactive offerings changed'; end if;

  if exists (
    (select row_data from batch_fourteen_protected_points except select to_jsonb(p) from public.syllabus_points p)
    union all
    (select to_jsonb(p) from public.syllabus_points p except select row_data from batch_fourteen_protected_points)
  ) then raise exception 'Batch fourteen stopped: syllabus points changed'; end if;

  if exists (
    (select row_data from batch_fourteen_protected_resources except select to_jsonb(r) from public.resources r)
    union all
    (select to_jsonb(r) from public.resources r except select row_data from batch_fourteen_protected_resources)
  ) then raise exception 'Batch fourteen stopped: resources changed'; end if;

  if exists (
    (select row_data from batch_fourteen_protected_other_offerings except
     select to_jsonb(o) from public.admission_offerings o where not (o.year = 2026 and o.status = 'published' and o.active = true and o.school_slug in ('hfnu','hnnu','slu','ahstu','tlu','fyut','auta','ahut')))
    union all
    (select to_jsonb(o) from public.admission_offerings o where not (o.year = 2026 and o.status = 'published' and o.active = true and o.school_slug in ('hfnu','hnnu','slu','ahstu','tlu','fyut','auta','ahut'))
     except select row_data from batch_fourteen_protected_other_offerings)
  ) then raise exception 'Batch fourteen stopped: non-target offerings changed'; end if;

  if (select count(*) from public.admission_offerings where status = 'published' and active = true) <> 367
     or (select count(distinct school_slug) from public.admission_offerings where status = 'published' and active = true) <> 41
     or (select count(*) from public.admission_offerings where year = 2026 and status = 'published' and active = true and school_slug in ('hfnu','hnnu','slu','ahstu','tlu','fyut','auta','ahut')) <> 100
     or (select sum(plan_count) from public.admission_offerings where year = 2026 and status = 'published' and active = true and school_slug in ('hfnu','hnnu','slu','ahstu','tlu','fyut','auta','ahut')) <> 7640 then
    raise exception 'Batch fourteen stopped: published offering totals are incorrect';
  end if;

  if exists (
    select 1 from public.admission_offerings o
    where o.year = 2026 and o.status = 'published' and o.active = true and o.school_slug in ('hfnu','hnnu','slu','ahstu','tlu','fyut','auta','ahut')
      and (cardinality(o.program_names) <> 1 or o.exam_scheme_id is null or o.plan_count is null or o.training_site is null
        or o.eligible_major_categories is null or cardinality(o.public_subjects) <> 2 or cardinality(o.professional_subjects) <> 2
        or o.charter_url is null or o.syllabus_url is null)
  ) then raise exception 'Batch fourteen stopped: an offering is incomplete or combines programs'; end if;

  if exists (
    select 1 from public.admission_offerings o
    where o.year = 2026 and o.status = 'published' and o.active = true and o.school_slug in ('hfnu','hnnu','slu','ahstu','tlu','fyut','auta','ahut')
    group by o.school_slug, o.exam_scheme_id
    having count(distinct jsonb_build_array(o.public_subjects, o.professional_subjects)::text) <> 1
  ) then raise exception 'Batch fourteen stopped: different exam subjects share one scheme'; end if;

  if exists (
    select 1 from public.admission_offerings o
    where o.year = 2026 and o.status = 'published' and o.active = true and o.school_slug in ('hfnu','hnnu','slu','ahstu','tlu','fyut','auta','ahut')
    group by o.school_slug, o.public_subjects, o.professional_subjects
    having count(distinct o.exam_scheme_id) <> 1
  ) then raise exception 'Batch fourteen stopped: identical exam schemes were duplicated'; end if;

  if (select count(*) from public.syllabus_points where status = 'published' and active = true) <> 1033
     or (select count(*) from public.resources where status = 'published') <> 80
     or (select count(*) from public.syllabus_points where status = 'draft' and active = false) <> 33
     or (select count(*) from public.admission_offerings where year = 2027 and status = 'draft' and active = false) <> 4 then
    raise exception 'Batch fourteen stopped: frozen content counts changed';
  end if;

  if (select version from public.content_versions where id = 'public-content') <= 115 then
    raise exception 'Batch fourteen stopped: public content version was not advanced';
  end if;
end $$;
